cat > /tmp/build_importers.go <<'GO'
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	f, _ := os.Open(os.Args[1])
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1<<24), 1<<24)
	importers := map[string]map[string]bool{}
	for scanner.Scan() {
		line := scanner.Text()
		idx := strings.Index(line, ":")
		if idx < 0 {
			continue
		}
		pkg := strings.TrimSpace(line[:idx])
		// gather list contents from each [...]
		rest := line[idx+1:]
		fields := strings.FieldsFunc(rest, func(r rune) bool {
			return r == '[' || r == ']' || r == ' '
		})
		seen := map[string]bool{}
		for _, fld := range fields {
			fld = strings.TrimSpace(fld)
			if !strings.HasPrefix(fld, "github.com/DocumentDrivenDX/agent") {
				continue
			}
			if fld == pkg {
				continue
			}
			if seen[fld] {
				continue
			}
			seen[fld] = true
			if importers[fld] == nil {
				importers[fld] = map[string]bool{}
			}
			importers[fld][pkg] = true
		}
	}
	pkgs := make([]string, 0, len(importers))
	for k := range importers {
		pkgs = append(pkgs, k)
	}
	// Just print map raw
	for k, v := range importers {
		ims := []string{}
		for x := range v {
			ims = append(ims, x)
		}
		fmt.Printf("%s => %s\n", k, strings.Join(ims, ", "))
	}
}
GO
