3	import (
4		"context"
5		"errors"
6		"fmt"
7		"sync/atomic"
8		"time"
9	
10		agent "github.com/DocumentDrivenDX/agent/internal/core"
11	)
12	
13	// DefaultProviderRequestTimeout bounds a single Chat / ChatStream call.
14	// A stalled TCP socket that has delivered headers but stopped emitting body
15	// bytes would otherwise pin a goroutine until the outer wall-clock frees it.
16	const DefaultProviderRequestTimeout = 15 * time.Minute
17	
18	// DefaultProviderIdleReadTimeout bounds the maximum idle gap between stream
19	// deltas. When streaming, a socket mid-stream-stall delivers no StreamDelta
20	// events and so cannot be caught by the event-level idle timer. This
21	// per-stream cap fires regardless.
22	const DefaultProviderIdleReadTimeout = 5 * time.Minute
23	
24	// ErrProviderRequestTimeout is returned by the deadline wrapper when a
25	// per-request bound (wall-clock or idle-read) fires. It is distinct from
26	// context.DeadlineExceeded so callers can tell a wrapper-triggered timeout
27	// from a caller-ctx cancel.
28	var ErrProviderRequestTimeout = errors.New("provider request timeout")
29	
30	// WrapProviderWithDeadlines returns p decorated with per-request deadlines.
31	// When p also implements agent.StreamingProvider, the returned wrapper
32	// implements StreamingProvider too.
33	func WrapProviderWithDeadlines(p agent.Provider) agent.Provider {
34		return WrapProviderWithDeadlinesTimeouts(p, DefaultProviderRequestTimeout, DefaultProviderIdleReadTimeout)
35	}
36	
37	// WrapProviderWithDeadlinesTimeouts is the explicit-timeout variant used by
38	// tests so they can exercise the bounds without waiting 15m.
39	func WrapProviderWithDeadlinesTimeouts(p agent.Provider, requestTimeout, idleTimeout time.Duration) agent.Provider {
40		if p == nil {
41			return p
42		}
43		tp := &timeoutProvider{
44			inner:          p,
45			requestTimeout: requestTimeout,
46			idleTimeout:    idleTimeout,
47		}
48		if _, ok := p.(agent.StreamingProvider); ok {
49			return &streamingTimeoutProvider{timeoutProvider: tp}
50		}
51		return tp
52	}
53	
54	// timeoutProvider enforces DefaultProviderRequestTimeout on Chat and forwards
55	// the agent library's optional metadata interfaces to the inner provider.
56	type timeoutProvider struct {
57		inner          agent.Provider
58		requestTimeout time.Duration
59		idleTimeout    time.Duration
60	}
61	
62	func (p *timeoutProvider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
63		if p.requestTimeout <= 0 {
64			return p.inner.Chat(ctx, messages, tools, opts)
65		}
66		cctx, cancel := context.WithTimeout(ctx, p.requestTimeout)
67		defer cancel()
68		resp, err := p.inner.Chat(cctx, messages, tools, opts)
69		if err != nil && ctx.Err() == nil && cctx.Err() == context.DeadlineExceeded {
70			return resp, fmt.Errorf("%w: wall-clock %s", ErrProviderRequestTimeout, p.requestTimeout)
71		}
72		return resp, err
73	}
74	
75	// SessionStartMetadata forwards to the inner provider when implemented so
76	// session.start telemetry is populated with the real provider name and model
77	// rather than "unknown".
78	func (p *timeoutProvider) SessionStartMetadata() (string, string) {
79		if mp, ok := p.inner.(interface {
80			SessionStartMetadata() (string, string)
81		}); ok {
82			return mp.SessionStartMetadata()
83		}
84		return "", ""
85	}
86	
87	// ChatStartMetadata forwards to the inner provider when implemented so chat
88	// span telemetry (provider_system, server_address, server_port) keeps flowing.
89	func (p *timeoutProvider) ChatStartMetadata() (string, string, int) {
90		if mp, ok := p.inner.(interface {
91			ChatStartMetadata() (string, string, int)
92		}); ok {
93			return mp.ChatStartMetadata()
94		}
95		return "", "", 0
96	}
97	
98	// RoutingReport forwards to the inner provider when implemented so routing
99	// wrappers continue to report selected provider and failover counts through
100	// the deadline wrapper.
101	func (p *timeoutProvider) RoutingReport() agent.RoutingReport {
102		if rr, ok := p.inner.(agent.RoutingReporter); ok {
103			return rr.RoutingReport()
104		}
105		return agent.RoutingReport{}
106	}
107	
108	// streamingTimeoutProvider adds ChatStream with an idle-read timer on top of
109	// timeoutProvider.
110	type streamingTimeoutProvider struct {
111		*timeoutProvider
112	}
113	
114	func (p *streamingTimeoutProvider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
115		sp, ok := p.inner.(agent.StreamingProvider)
116		if !ok {
117			return nil, fmt.Errorf("provider does not support streaming")
118		}
119	
120		requestTimeout := p.requestTimeout
121		idleTimeout := p.idleTimeout
122	
123		// Derive the per-stream context. It may already be unbounded if
124		// requestTimeout is zero, in which case we only apply the idle-read cap.
125		var (
126			cctx   context.Context
127			cancel context.CancelFunc
128		)
129		if requestTimeout > 0 {
130			cctx, cancel = context.WithTimeout(ctx, requestTimeout)
131		} else {
132			cctx, cancel = context.WithCancel(ctx)
133		}
134	
135		ch, err := sp.ChatStream(cctx, messages, tools, opts)
136		if err != nil {
137			cancel()
138			if ctx.Err() == nil && cctx.Err() == context.DeadlineExceeded {
139				return nil, fmt.Errorf("%w: wall-clock %s", ErrProviderRequestTimeout, requestTimeout)
140			}
141			return nil, err
142		}
143	
144		out := make(chan agent.StreamDelta, 1)
145		go func() {
146			defer cancel()
147			defer close(out)
148	
149			var idle *time.Timer
150			var idleC <-chan time.Time
151			if idleTimeout > 0 {
152				idle = time.NewTimer(idleTimeout)
153				idleC = idle.C
154				defer idle.Stop()
155			}
156	
157			// emitted ensures we only synthesize one error delta per stream.
158			var emitted atomic.Bool
159			emit := func(delta agent.StreamDelta) bool {
160				select {
161				case out <- delta:
162					return true
163				case <-ctx.Done():
164					return false
165				}
166			}
167	
168			for {
169				select {
170				case delta, ok := <-ch:
171					if !ok {
172						return
173					}
174					if idle != nil {
175						if !idle.Stop() {
176							select {
177							case <-idle.C:
178							default:
179							}
180						}
181						idle.Reset(idleTimeout)
182					}
183					if !emit(delta) {
184						return
185					}
186					if delta.Done || delta.Err != nil {
187						return
188					}
189				case <-idleC:
190					if !emitted.CompareAndSwap(false, true) {
191						return
192					}
193					cancel() // hard-abort the underlying HTTP read
194					emit(agent.StreamDelta{
195						Err: fmt.Errorf("%w: idle-read %s", ErrProviderRequestTimeout, idleTimeout),
196					})
197					// Drain the inner channel so the producer goroutine in the
198					// underlying SDK returns, but only briefly — we already
199					// signaled downstream.
200					drainDeadline := time.NewTimer(2 * time.Second)
201					defer drainDeadline.Stop()
202					for {
203						select {
204						case _, ok := <-ch:
205							if !ok {
206								return
207							}
208						case <-drainDeadline.C:
209							return
210						}
211					}
212				case <-cctx.Done():
213					// Distinguish wrapper-triggered wall-clock timeout from a
214					// caller ctx cancel. When ctx is alive but cctx is dead by
215					// DeadlineExceeded, we fired our own request-level cap.
216					if ctx.Err() == nil && cctx.Err() == context.DeadlineExceeded {
217						if !emitted.CompareAndSwap(false, true) {
218							return
219						}
220						emit(agent.StreamDelta{
221							Err: fmt.Errorf("%w: wall-clock %s", ErrProviderRequestTimeout, requestTimeout),
222						})
223					}
224					// Either way, drain briefly then exit.
225					drainDeadline := time.NewTimer(2 * time.Second)
226					defer drainDeadline.Stop()
227					for {
228						select {
229						case _, ok := <-ch:
230							if !ok {
231								return
232							}
233						case <-drainDeadline.C:
234							return
235						}
236					}
237				}
238			}
239		}()
240	
241		return out, nil
242	}
243	
244	var (
245		_ agent.Provider          = (*timeoutProvider)(nil)
246		_ agent.Provider          = (*streamingTimeoutProvider)(nil)
247		_ agent.StreamingProvider = (*streamingTimeoutProvider)(nil)
248	)
